+'use strict'
+
+const test = require('node:test')
+const Request = require('../lib/request')
+
+test('.port parses port correctly', (t) => {
+  const fixtures = [
+    {
+      expected: 80,
+      req: {
+        headers: {
+          host: 'example.com:80'
+        }
+      }
+    },
+    {
+      expected: 443,
+      req: {
+        headers: {
+          host: 'example.com:443'
+        }
+      }
+    },
+    {
+      expected: 80,
+      req: {
+        headers: {
+          host: '[::1]:80'
+        }
+      }
+    },
+    {
+      expected: 443,
+      req: {
+        headers: {
+          host: '[::1]:443'
+        }
+      }
+    },
+    {
+      expected: null,
