+        headers: {
+          host: '[::1]'
+        }
+      }
+    },
+    {
+      expected: 80,
+      req: {
+        headers: {
+          ':authority': '1.2.3.4:80'
+        }
+      }
+    },
+    {
+      expected: null,
+      req: {
+        headers: {}
+      }
+    }
+  ]
+
