tool_input.new_string:
if (typeof tp === 'number') {
  // Support trusting hop count.
  // The trust decision is based on the position of the address only, so a
  // missing address must not invalidate the hop: the socket address is
  // undefined when the server listens on a unix socket or a Windows named
  // pipe (e.g. iisnode), and those deployments still have a trusted proxy
  // in front of them.
  return function (a, i) { return i < tp }
}
